def max_significance(n, m, d, physics_cups, informatics_cups):
    physics_cups.sort(key=lambda x: (-x[0], -x[1]))
    informatics_cups.sort(key=lambda x: (-x[0], -x[1]))

    def binary_search(cups, d):
        left, right = 0, len(cups)
        while left < right:
            mid = (left + right + 1) // 2
            if sum(cups[i][1] for i in range(mid)) <= d:
                left = mid
            else:
                right = mid - 1
        return left

    def dfs(i, j, current_width, current_sum):
        nonlocal max_sig
        if i == n or j == m:
            return
        if current_width + physics_cups[i][1] <= d:
            dfs(i + 1, j, current_width + physics_cups[i][1], current_sum + physics_cups[i][0])
        if current_width + informatics_cups[j][1] <= d:
            dfs(i, j + 1, current_width + informatics_cups[j][1], current_sum + informatics_cups[j][0])

    min_physics_width = physics_cups[0][1]
    min_informatics_width = informatics_cups[0][1]

    if min_physics_width + min_informatics_width > d:
        return 0

    max_sig = 0

    # Check combinations of Physics and Informatics cups
    for i in range(min_physics_width, d - min_informatics_width + 1, min_physics_width):
        for j in range(min_informatics_width, d - min_physics_width + 1, min_informatics_width):
            if i + j > d:
                continue
            current_sum = 0
            for k in range(n):
                if physics_cups[k][1] <= i:
                    current_sum += physics_cups[k][0]
                else:
                    break
            for l in range(m):
                if informatics_cups[l][1] <= j:
                    current_sum += informatics_cups[l][0]
                else:
                    break
            max_sig = max(max_sig, current_sum)

    return max_sig

