def max_significance(n, m, d, physics_cups, informatics_cups):
    physics_cups.sort(key=lambda x: (-x[0], -x[1]))
    informatics_cups.sort(key=lambda x: (-x[0], -x[1]))

    def binary_search(cups, target_width):
        left, right = 0, len(cups) - 1
        while left <= right:
            mid = (left + right) // 2
            if cups[mid][1] > target_width:
                right = mid - 1
            else:
                left = mid + 1
        return left

    best_sum = 0
    for i in range(len(physics_cups)):
        if physics_cups[i][1] > d:
            break
        remaining_width = d - physics_cups[i][1]
        j = binary_search(informatics_cups, remaining_width)
        current_sum = physics_cups[i][0]
        for k in range(j):
            current_sum += informatics_cups[k][0]
            if current_sum > best_sum:
                best_sum = current_sum
            if remaining_width < informatics_cups[k][1]:
                break
        remaining_width -= informatics_cups[j-1][1] if j > 0 else 0
        while j < len(informatics_cups) and informatics_cups[j][1] <= remaining_width:
            current_sum += informatics_cups[j][0]
            if current_sum > best_sum:
                best_sum = current_sum
            j += 1

    return best_sum

